public static boolean isValidDate(String date) {
    if (date == null || !date.matches("\\d{4}-\\d{2}-\\d{2}")) {
        return false;
    }

    int year = Integer.parseInt(date.substring(0, 4)); // Extract the year
    int month = Integer.parseInt(date.substring(5, 7)); // Extract the month
    int day = Integer.parseInt(date.substring(8, 10)); // Extract the day

    if (month < 1 || month > 12) {
        return false; // Invalid month
    }

    if (day < 1 || day > 31) {
        return false; // Invalid day
    }

    switch (month) {
        case 4:
        case 6:
        case 9:
        case 11:
            if (day > 30) {
                return false; // Invalid day for April, June, September and November
            }
            break;
        case 2:
            // February
            int leapYear = year % 4 == 0 ? 1 : 0;
            if (leapYear == 1 && day > 29) {
                return false; // Invalid day for leap year
            }
            if (leapYear == 0 && day > 28) {
                return false; // Invalid day for non-leap year
            }
            break;
        default:
            break;
    }

    return true; // Valid date
}

