    // Generate a complete bipartite graph with n nodes on each side
    // V = Unknown
    // E = Object (source, target)
    int n = (int)(Math.sqrt(resultMap.size()) + 0.5);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            V source = resultMap.get("p" + i);
            V target = resultMap.get("q" + j);
            E edge = new Edge(source, target);
            target.addEdge(edge);
