public void generateCompleteBipartiteGraph(Graph<V,E> target, Map<String,V> resultMap) {
    int numVertices = target.getNumVertices();
    int numEdges = target.getNumEdges();

    // Split the vertices into two sets: A and B
    Set<V> setA = new HashSet<>();
    Set<V> setB = new HashSet<>();
    for (V vertex : target.getVertices()) {
        if (vertex.getLabel() == "A") {
            setA.add(vertex);
        } else {
            setB.add(vertex);
        }
    }

    // Order the vertices in setA and setB
    List<V> orderedA = new ArrayList<>(setA);
    List<V> orderedB = new ArrayList<>(setB);
    Collections.sort(orderedA);
    Collections.sort(orderedB);

    // Iterate over the vertices in A and connect them to the corresponding vertices in B
    for (V vertexA : orderedA) {
        for (V vertexB : orderedB) {
            target.addEdge(vertexA, vertexB);
        }
    }
}

