public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize an empty path
    GraphPath<V, E> path = new GraphPath<>();

    // Iterate over the set of edges in the tour
    for (E edge : tour) {
      // Get the vertices of the edge
      V source = graph.getEdgeSource(edge);
      V target = graph.getEdgeTarget(edge);

      // Add the edge to the path
      path.addEdge(edge);

      // Set the source and target vertices of the edge
      edge.setSource(source);
      edge.setTarget(target);
    }

    // Return the path
    return path;
  }

protected GraphPath<V, E> edgeSetToTour(final Set<E> tour, final Graph<V, E> graph) {
    final GraphPath<V, E> path = new GraphPath<>();

