public static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
	long sum = 0;
	List<Integer> suffixSum = new ArrayList<>();
	if (bounds == null) {
		throw new IllegalArgumentException("Bounds cannot be null");
	}
	for (Integer i : bounds) {
		sum += i;
		suffixSum.add(sum);
	}
	return new Pair(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    Long totalSum = 0L;
    List<Integer> suffixSum = new ArrayList<Integer>(bounds.size());
    for (int i = 0; i < bounds.size(); i++) {
        totalSum += bounds.get(i);
        suffixSum.add(totalSum);
    }
    return new Pair<List<Integer>, Long>(suffixSum, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>();
    long totalSum = 0;
    for (int i = 0; i < bounds.size(); i++) {
        suffixSumList.add(bounds.get(i) + (i == 0 ? 0 : suffixSumList.get(i - 1)));
        totalSum += bounds.get(i);
    }
    return new Pair<>(suffixSumList, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
        List<Integer> suffixSum = new ArrayList<>();
        long sum = 0;
        for (Integer bound : bounds) {
            suffixSum.add(bound);
            sum += bound;
        }
        return new Pair<>(suffixSum, sum);
    }

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int[] suffixSum = new int[bounds.size()];
    int sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffixSum[i] = sum += bounds.get(i);
    }
    return new Pair<List<Integer>, Long>(Arrays.asList(suffixSum), (long) sum);
}

