    String result = path;
    for (String component : relativePath.split("/")) {
        if (component.equals(".")) {
            continue;
        } else if (component.equals("..")) {
            result = result.substring(0, result.lastIndexOf("/"));
        } else {
            result += "/" + component;
        }
    }
    return result;
}

