public static int nextPrime(int desiredCapacity) {
    /* Retrieve a prime number that is >= desiredCapacity and within 11% of desiredCapacity if desiredCapacity >= 1000 */
    // Use the Sieve of Eratosthenes to generate prime numbers
    boolean[] isComposite = new boolean[Math.max(desiredCapacity, 1000)];
    int largestFoundPrime = -1;
    for (int i = 2; i < Math.sqrt(Math.max(desiredCapacity, 1000)); i++) {
        if (!isComposite[i]) {
            int multiple = i * 2;
            while (multiple < Math.max(desiredCapacity, 1000)) {
                isComposite[multiple] = true;
                multiple += i;
            }
            if (largestFoundPrime < i) {
                largestFoundPrime = i;
            }
        }
    }
    // Check if the desired capacity is already a prime number
    if (isComposite[desiredCapacity]) {
        // Check if the next prime number is within 11% of desiredCapacity
        if (largestFoundPrime > 0 && largestFoundPrime / (double)desiredCapacity >= 1 - 0.11) {
            return largestFoundPrime;
        }
    } else {
        // If the desired capacity is not a prime number, return it directly
        return desiredCapacity;
    }
    // If the next prime number is not within 11% of desiredCapacity, return the largest prime number found
    return largestFoundPrime;
}

